record.field:
if env.context.get('conversation_id'):
    conversation = env['ak_ai.conversation'].browse(int(env.context['conversation_id']))
    if conversation.exists():
        result = conversation.action_execute_last_code()
        if result.get('success'):
            action = {
                'type': 'ir.actions.client',
                'tag': 'display_notification',
                'params': {
                    'title': 'Başarılı',
                    'message': result.get('message', 'Kod başarıyla çalıştırıldı'),
                    'type': 'success',
                    'sticky': False,
                }
            }
        else:
            action = {
                'type': 'ir.actions.client',
                'tag': 'display_notification',
                'params': {
                    'title': 'Hata',
                    'message': result.get('message', 'Kod çalıştırılırken hata oluştu'),
                    'type': 'danger',
                    'sticky': True,
                }
            }
